// - v32 (v2.7 Phase 2 — the proto ↔ session SEAM, task 01KY50ZPVSMZPSY351VJNR7Z0F) adds
//   `agent_session_prototypes`, the MANY-TO-MANY link between an agent session and the prototypes
//   it works (shaped exactly like `agent_session_specs`, v20). `session_id` (FK → agent_sessions,
//   CASCADE) + `prototype_id` (FK → prototypes, CASCADE) form the composite PRIMARY KEY (a
//   prototype is in a session's set at most once; the auto-map's ADD is idempotent), plus an
//   epoch-ms `created_at`. NO scalar pin — the session (not the terminal) is the unit of work.
diesel::table! {
    agent_session_prototypes (session_id, prototype_id) {
        session_id -> Text,
        prototype_id -> Text,
        created_at -> BigInt,
    }
}

// - v48 (the consent check's lifetime fix) adds `human_turns`: the LAST prompt a human submitted
//   on a terminal, keyed by `terminal_id` (one row per terminal). It carries the turn's IDENTITY
//   (`turn_id` — Claude Code's `prompt_id` when it sends one), the raw `prompt` and its
//   `submitted_at` (epoch ms). NO `joinable!` and no FK: the `UserPromptSubmit` hook that writes
//   this row must never fail on a terminal nyx holds no row for.
// - v49 (one turn, one commitment) adds `consumed_by`: the run whose consent that turn has ALREADY
//   authorised, NULL while nobody has spent it. Nullable and FK-less on purpose — a CASCADE from a
//   deleted run would un-spend a turn that really was spent.
diesel::table! {
    human_turns (terminal_id) {
        terminal_id -> Text,
        turn_id -> Text,
        prompt -> Text,
        submitted_at -> BigInt,
        consumed_by -> Nullable<Text>,
    }
}

// - the app-level preference store adds `app_settings`: ONE row per global preference of the
//   installation, keyed by its stable `key` (a constant in `db.rs`, never a literal at a call
//   site). `value` is the serialized preference — a scalar verbatim, a structured one as JSON —
//   and `updated_at` is epoch ms. NO `joinable!` and no FK: an app preference is scoped to the
//   installation, so it references nothing and nothing cascades it away. The ABSENCE of a row is
//   the meaningful "user expressed nothing" state, so clearing a preference deletes its row.
diesel::table! {
    app_settings (key) {
        key -> Text,
        value -> Text,
        updated_at -> BigInt,
    }
}

